/* Frontière efficiente interactive — deux actifs */
(function () {
  var svg = document.getElementById("ef-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id, t){ var e = document.getElementById(id); if (e) e.textContent = t; }

  function draw() {
    var muA=v("ef-muA"), sA=v("ef-sA"), muB=v("ef-muB"), sB=v("ef-sB"), rho=v("ef-rho"), w=v("ef-w")/100;
    setT("ef-muA-o", v("ef-muA")+"%"); setT("ef-sA-o", v("ef-sA")+"%");
    setT("ef-muB-o", v("ef-muB")+"%"); setT("ef-sB-o", v("ef-sB")+"%");
    setT("ef-rho-o", v("ef-rho").toFixed(2)); setT("ef-w-o", v("ef-w")+"%");

    var N=100, pts=[], minS=1e9, minI=0;
    for (var i=0;i<=N;i++){
      var wa=i/N, wb=1-wa;
      var mu=wa*muA+wb*muB;
      var varr=wa*wa*sA*sA + wb*wb*sB*sB + 2*wa*wb*rho*sA*sB;
      if (varr<0) varr=0;
      var s=Math.sqrt(varr);
      pts.push({s:s, mu:mu});
      if (s<minS){ minS=s; minI=i; }
    }
    var cmu=w*muA+(1-w)*muB;
    var cvar=w*w*sA*sA+(1-w)*(1-w)*sB*sB+2*w*(1-w)*rho*sA*sB; if(cvar<0)cvar=0;
    var cs=Math.sqrt(cvar);
    setT("ef-mu", cmu.toFixed(2)+"%"); setT("ef-sig", cs.toFixed(2)+"%");
    setT("ef-mvpw", Math.round(minI/N*100)+"% / "+Math.round((1-minI/N)*100)+"%");

    var L=48,R=16,T=14,B=34,W=520,H=340, pw=W-L-R, ph=H-T-B;
    var maxX=Math.max(sA, sB); for (var j=0;j<pts.length;j++) if(pts[j].s>maxX) maxX=pts[j].s;
    var xMax=Math.ceil(maxX*1.12/2)*2; if(xMax<=0) xMax=2;
    var yLo=Math.min(muA,muB), yHi=Math.max(muA,muB); var pad=(yHi-yLo)*0.18||1; yLo-=pad; yHi+=pad;
    function px(x){ return L + x/xMax*pw; }
    function py(y){ return T + (yHi-y)/(yHi-yLo)*ph; }

    var g="";
    var nx=4;
    for (var k=0;k<=nx;k++){ var xv=xMax*k/nx, X=px(xv);
      g+='<line class="grid" x1="'+X+'" y1="'+T+'" x2="'+X+'" y2="'+(T+ph)+'"/>';
      g+='<text class="tick" x="'+X+'" y="'+(T+ph+13)+'" text-anchor="middle">'+xv.toFixed(0)+'</text>';
    }
    for (var m=0;m<=4;m++){ var yv=yLo+(yHi-yLo)*m/4, Y=py(yv);
      g+='<line class="grid" x1="'+L+'" y1="'+Y+'" x2="'+(L+pw)+'" y2="'+Y+'"/>';
      g+='<text class="tick" x="'+(L-6)+'" y="'+(Y+3)+'" text-anchor="end">'+yv.toFixed(1)+'</text>';
    }
    g+='<line class="axis" x1="'+L+'" y1="'+(T+ph)+'" x2="'+(L+pw)+'" y2="'+(T+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+T+'" x2="'+L+'" y2="'+(T+ph)+'"/>';

    var poly="";
    for (var p=0;p<pts.length;p++) poly += px(pts[p].s).toFixed(1)+","+py(pts[p].mu).toFixed(1)+" ";
    g+='<polyline class="curve" points="'+poly.trim()+'"/>';

    g+='<circle class="dot-a" cx="'+px(sA)+'" cy="'+py(muA)+'" r="4"/><text class="alab" x="'+(px(sA)+7)+'" y="'+(py(muA)-6)+'">A</text>';
    g+='<circle class="dot-a" cx="'+px(sB)+'" cy="'+py(muB)+'" r="4"/><text class="alab" x="'+(px(sB)+7)+'" y="'+(py(muB)-6)+'">B</text>';
    var mv=pts[minI];
    g+='<circle class="dot-mvp" cx="'+px(mv.s)+'" cy="'+py(mv.mu)+'" r="5"/><text class="alab" x="'+(px(mv.s)-8)+'" y="'+(py(mv.mu)+4)+'" text-anchor="end">MVP</text>';
    g+='<circle class="dot-cur" cx="'+px(cs)+'" cy="'+py(cmu)+'" r="6"/>';

    g+='<text class="alab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">σ (%)</text>';
    g+='<text class="alab" transform="translate(13,'+(T+ph/2)+') rotate(-90)" text-anchor="middle">μ (%)</text>';

    svg.innerHTML=g;
  }

  ["ef-muA","ef-sA","ef-muB","ef-sB","ef-rho","ef-w"].forEach(function(id){
    var e=document.getElementById(id); if(e) e.addEventListener("input", draw);
  });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
